import * as Haptics from 'expo-haptics';
import React, { useCallback, useRef } from 'react';
import { Animated, Pressable, StyleSheet } from 'react-native';
import { Text } from 'react-native-paper';

import { BorderRadius, Spacing, Typography } from '../constants/designTokens';
import { useTheme } from '../hooks/useTheme';

interface ActionCardEnhancedProps {
  readonly title: string;
  readonly description: string;
  readonly icon: string;
  readonly onPress: () => void;
  readonly variant: 'info' | 'success' | 'warning' | 'brand';
}

export const ActionCardEnhanced: React.FC<ActionCardEnhancedProps> = ({
  title,
  description,
  icon,
  onPress,
  variant,
}) => {
  const { colors } = useTheme();
  const scaleAnim = useRef(new Animated.Value(1)).current;
  const opacityAnim = useRef(new Animated.Value(1)).current;
  const iconScaleAnim = useRef(new Animated.Value(1)).current;

  const handlePressIn = useCallback(() => {
    // Light haptic feedback on press
    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);

    Animated.parallel([
      Animated.spring(scaleAnim, {
        toValue: 0.96,
        useNativeDriver: true,
        tension: 400,
        friction: 8,
      }),
      Animated.timing(opacityAnim, {
        toValue: 0.85,
        duration: 120,
        useNativeDriver: true,
      }),
      // Subtle icon scale animation
      Animated.spring(iconScaleAnim, {
        toValue: 0.95,
        useNativeDriver: true,
        tension: 500,
        friction: 6,
      }),
    ]).start();
  }, [scaleAnim, opacityAnim, iconScaleAnim]);

  const handlePressOut = useCallback(() => {
    Animated.parallel([
      Animated.spring(scaleAnim, {
        toValue: 1,
        useNativeDriver: true,
        tension: 400,
        friction: 8,
      }),
      Animated.timing(opacityAnim, {
        toValue: 1,
        duration: 120,
        useNativeDriver: true,
      }),
      Animated.spring(iconScaleAnim, {
        toValue: 1,
        useNativeDriver: true,
        tension: 500,
        friction: 6,
      }),
    ]).start();
  }, [scaleAnim, opacityAnim, iconScaleAnim]);

  const handlePress = useCallback(() => {
    // Success haptic feedback on successful action
    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
    onPress();
  }, [onPress]);

  const variantStyles = {
    info: {
      backgroundColor: colors.semantic.info.light + '40',
      iconBg: colors.semantic.info.main + '15',
      iconBorder: colors.semantic.info.main + '25',
      shadowColor: colors.semantic.info.main,
    },
    success: {
      backgroundColor: colors.semantic.success.light + '40',
      iconBg: colors.semantic.success.main + '15',
      iconBorder: colors.semantic.success.main + '25',
      shadowColor: colors.semantic.success.main,
    },
    warning: {
      backgroundColor: colors.semantic.warning.light + '40',
      iconBg: colors.semantic.warning.main + '15',
      iconBorder: colors.semantic.warning.main + '25',
      shadowColor: colors.semantic.warning.main,
    },
    brand: {
      backgroundColor: colors.primary[100] + '60',
      iconBg: colors.primary[500] + '15',
      iconBorder: colors.primary[500] + '25',
      shadowColor: colors.primary[500],
    },
  };

  return (
    <Animated.View
      style={[
        styles.container,
        {
          transform: [{ scale: scaleAnim }],
          opacity: opacityAnim,
          shadowColor: variantStyles[variant].shadowColor,
        },
      ]}
    >
      <Pressable
        onPressIn={handlePressIn}
        onPressOut={handlePressOut}
        onPress={handlePress}
        style={[
          styles.content,
          { backgroundColor: variantStyles[variant].backgroundColor },
        ]}
        accessible
        accessibilityRole="button"
        accessibilityLabel={`${title}: ${description}`}
        accessibilityHint="Tocca per accedere a questa funzionalità"
      >
        <Animated.View
          style={[
            styles.iconContainer,
            {
              backgroundColor: variantStyles[variant].iconBg,
              borderColor: variantStyles[variant].iconBorder,
              transform: [{ scale: iconScaleAnim }],
            },
          ]}
        >
          <Text
            style={styles.icon}
            accessible={false} // Icon is decorative, description is in accessibilityLabel
          >
            {icon}
          </Text>
        </Animated.View>
        <Text
          variant="titleMedium"
          style={styles.title}
          accessible={false} // Combined in parent accessibilityLabel
        >
          {title}
        </Text>
        <Text
          style={styles.description}
          accessible={false} // Combined in parent accessibilityLabel
        >
          {description}
        </Text>
      </Pressable>
    </Animated.View>
  );
};

const styles = StyleSheet.create({
  container: {
    width: '100%',
    borderRadius: BorderRadius.xl,
    shadowOffset: { width: 0, height: 6 },
    shadowOpacity: 0.08,
    shadowRadius: 16,
    marginBottom: Spacing[4],
    elevation: 4, // Android shadow
  },
  content: {
    alignItems: 'center',
    justifyContent: 'center',
    padding: Spacing[4],
    borderRadius: BorderRadius.xl,
    minHeight: 120,
  },
  iconContainer: {
    width: 56,
    height: 56,
    borderRadius: 28,
    alignItems: 'center',
    justifyContent: 'center',
    marginBottom: Spacing[3],
    borderWidth: 1,
  },
  icon: {
    fontSize: 28,
  },
  title: {
    textAlign: 'center',
    fontSize: Typography.sizes.base,
    fontWeight: Typography.weights.bold,
    marginBottom: Spacing[1],
  },
  description: {
    textAlign: 'center',
    fontSize: Typography.sizes.xs,
    lineHeight: Typography.sizes.xs * 1.4,
    color: '#666',
  },
});

export default ActionCardEnhanced;

import React, { useEffect, useRef } from 'react';
import type { ViewStyle } from 'react-native';
import { Animated } from 'react-native';

export type TransitionType =
  | 'fadeIn'
  | 'slideUp'
  | 'slideDown'
  | 'slideLeft'
  | 'slideRight'
  | 'scale'
  | 'bounce'
  | 'elastic';

interface AnimatedTransitionProps {
  readonly children: React.ReactNode;
  readonly type?: TransitionType;
  readonly duration?: number;
  readonly delay?: number;
  readonly style?: ViewStyle;
  readonly onComplete?: () => void;
  readonly trigger?: boolean; // Per ri-attivare l'animazione
}

export const AnimatedTransition: React.FC<AnimatedTransitionProps> = ({
  children,
  type = 'fadeIn',
  duration = 600,
  delay = 0,
  style,
  onComplete,
  trigger = true,
}) => {
  const animatedValue = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    if (trigger !== null) {
      animatedValue.setValue(0);

      const startAnimation = () => {
        const animation = getAnimation(type, animatedValue, duration);

        if (animation) {
          animation.start(() => {
            onComplete?.();
          });
        }
      };

      if (delay > 0) {
        setTimeout(startAnimation, delay);
      } else {
        startAnimation();
      }
    }
  }, [trigger, type, duration, delay, animatedValue, onComplete]);

  const getAnimation = (
    animationType: TransitionType,
    value: Animated.Value,
    animationDuration: number
  ) => {
    switch (animationType) {
      case 'bounce':
        return Animated.spring(value, {
          toValue: 1,
          tension: 100,
          friction: 8,
          useNativeDriver: true,
        });
      case 'elastic':
        return Animated.spring(value, {
          toValue: 1,
          tension: 120,
          friction: 6,
          useNativeDriver: true,
        });
      default:
        return Animated.timing(value, {
          toValue: 1,
          duration: animationDuration,
          useNativeDriver: true,
        });
    }
  };

  const getAnimatedStyle = () => {
    switch (type) {
      case 'fadeIn':
        return {
          opacity: animatedValue,
        };
      case 'slideUp':
        return {
          opacity: animatedValue,
          transform: [
            {
              translateY: animatedValue.interpolate({
                inputRange: [0, 1],
                outputRange: [50, 0],
              }),
            },
          ],
        };
      case 'slideDown':
        return {
          opacity: animatedValue,
          transform: [
            {
              translateY: animatedValue.interpolate({
                inputRange: [0, 1],
                outputRange: [-50, 0],
              }),
            },
          ],
        };
      case 'slideLeft':
        return {
          opacity: animatedValue,
          transform: [
            {
              translateX: animatedValue.interpolate({
                inputRange: [0, 1],
                outputRange: [50, 0],
              }),
            },
          ],
        };
      case 'slideRight':
        return {
          opacity: animatedValue,
          transform: [
            {
              translateX: animatedValue.interpolate({
                inputRange: [0, 1],
                outputRange: [-50, 0],
              }),
            },
          ],
        };
      case 'scale':
      case 'bounce':
      case 'elastic':
        return {
          opacity: animatedValue,
          transform: [
            {
              scale: animatedValue.interpolate({
                inputRange: [0, 1],
                outputRange: [0.3, 1],
              }),
            },
          ],
        };
      default:
        return {
          opacity: animatedValue,
        };
    }
  };

  return (
    <Animated.View style={[getAnimatedStyle(), style]}>
      {children}
    </Animated.View>
  );
};

// Componente per liste animate
interface AnimatedListProps {
  readonly children: React.ReactNode[];
  readonly itemDelay?: number;
  readonly type?: TransitionType;
  readonly duration?: number;
  readonly startDelay?: number;
}

export const AnimatedList: React.FC<AnimatedListProps> = ({
  children,
  itemDelay = 100,
  type = 'slideUp',
  duration = 600,
  startDelay = 0,
}) => {
  return (
    <>
      {React.Children.map(children, (child, index) => {
        const uniqueKey = `animated-${Date.now()}-${Math.random()
          .toString(36)
          .substr(2, 9)}-${index}`;
        return (
          <AnimatedTransition
            key={uniqueKey}
            type={type}
            duration={duration}
            delay={startDelay + index * itemDelay}
          >
            {child}
          </AnimatedTransition>
        );
      })}
    </>
  );
};

// Hook per animazioni programmatiche
export const useAnimatedValue = (initialValue = 0) => {
  const animatedValue = useRef(new Animated.Value(initialValue)).current;

  const animateTo = (
    toValue: number,
    callback?: () => void,
    duration = 300
  ) => {
    Animated.timing(animatedValue, {
      toValue,
      duration,
      useNativeDriver: true,
    }).start(callback);
  };

  const springTo = (
    toValue: number,
    callback?: () => void,
    config = { tension: 100, friction: 8 }
  ) => {
    Animated.spring(animatedValue, {
      toValue,
      ...config,
      useNativeDriver: true,
    }).start(callback);
  };

  const pulse = (callback?: () => void, scale = 1.1, duration = 150) => {
    Animated.sequence([
      Animated.timing(animatedValue, {
        toValue: scale,
        duration,
        useNativeDriver: true,
      }),
      Animated.timing(animatedValue, {
        toValue: 1,
        duration,
        useNativeDriver: true,
      }),
    ]).start(callback);
  };

  return {
    value: animatedValue,
    animateTo,
    springTo,
    pulse,
  };
};

export default AnimatedTransition;

import React from 'react';
import type { GestureResponderEvent, ViewStyle } from 'react-native';
import {
  Animated,
  Platform,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from 'react-native';

import {
  Accessibility,
  BorderRadius,
  Colors,
  Shadows,
  Spacing,
  Typography,
} from '../constants/designTokens';
import { useAnimatedPress } from '../hooks/useAnimatedPress';

interface EnhancedCardProps {
  readonly title: string;
  readonly subtitle?: string;
  readonly icon: string;
  readonly onPress?: (event: GestureResponderEvent) => void;
  readonly variant?: 'default' | 'primary' | 'elevated';
  readonly size?: 'compact' | 'standard' | 'large';
  readonly disabled?: boolean;
  readonly showArrow?: boolean;
  readonly customStyle?: ViewStyle;
  readonly children?: React.ReactNode;
  readonly accessibilityLabel?: string;
  readonly accessibilityHint?: string;
}

export const EnhancedCard: React.FC<EnhancedCardProps> = ({
  title,
  subtitle,
  icon,
  onPress,
  variant = 'default',
  size = 'standard',
  disabled = false,
  showArrow = true,
  customStyle,
  children,
  accessibilityLabel,
  accessibilityHint,
}) => {
  // Use custom hook for animations - eliminates 40+ lines of duplicate code
  const { shadowValue, handlePressIn, handlePressOut, animatedStyle } =
    useAnimatedPress({ scaleValue: 0.98, minOpacity: 0.85 });

  // Dynamic styles based on variant and size
  const getCardStyle = () => {
    const baseStyles = [
      styles.baseCard,
      styles[`${variant}Card`],
      styles[`${size}Card`],
      customStyle,
    ];

    // Add conditional styles separately to avoid type conflicts
    if (disabled !== null !== null) {
      void baseStyles.push(styles.disabledCard);
    }

    return baseStyles;
  };

  // Accessibility configuration
  const accessibilityConfig = {
    accessible: true,
    accessibilityLabel:
      accessibilityLabel ??
      `${title}${
        subtitle !== undefined && subtitle !== null && subtitle !== ''
          ? `, ${subtitle}`
          : ''
      }`,
    accessibilityHint:
      accessibilityHint ?? (onPress ? 'Tocca per aprire' : undefined),
    accessibilityState: { disabled },
    ...Accessibility.touchTarget,
  };

  return (
    <Animated.View style={[animatedStyle]}>
      <TouchableOpacity
        style={getCardStyle()}
        onPress={onPress}
        onPressIn={handlePressIn}
        onPressOut={handlePressOut}
        disabled={disabled}
        activeOpacity={1}
        {...accessibilityConfig}
      >
        <View style={styles.cardContent}>
          {/* Icon Section */}
          <View style={styles.iconSection}>
            <View
              style={[
                styles.iconContainer,
                styles[`${variant}IconContainer`],
                styles[`${size}IconContainer`],
              ]}
            >
              <Text
                style={[
                  styles.icon,
                  styles[`${variant}Icon`],
                  styles[`${size}Icon`],
                ]}
              >
                {icon}
              </Text>
            </View>
          </View>

          {/* Text Section */}
          <View style={styles.textSection}>
            <Text
              style={[
                styles.title,
                styles[`${variant}Title`],
                styles[`${size}Title`],
              ]}
              numberOfLines={2}
              ellipsizeMode="tail"
            >
              {title}
            </Text>

            {subtitle !== undefined && subtitle !== null && subtitle !== '' && (
              <Text
                style={[
                  styles.subtitle,
                  styles[`${variant}Subtitle`],
                  styles[`${size}Subtitle`],
                ]}
                numberOfLines={2}
                ellipsizeMode="tail"
              >
                {subtitle}
              </Text>
            )}

            {children}
          </View>

          {/* Arrow Section */}
          {showArrow && onPress && !disabled && (
            <View style={styles.arrowSection}>
              <Animated.Text
                style={[
                  styles.arrow,
                  styles[`${variant}Arrow`],
                  {
                    transform: [
                      {
                        translateX: shadowValue.interpolate({
                          inputRange: [0, 1],
                          outputRange: [0, 2],
                        }),
                      },
                    ],
                  },
                ]}
              >
                →
              </Animated.Text>
            </View>
          )}
        </View>
      </TouchableOpacity>
    </Animated.View>
  );
};

/* eslint-disable react-native/no-unused-styles */
const styles = StyleSheet.create({
  // Base Card Styles
  baseCard: {
    borderRadius: BorderRadius.xl,
    marginBottom: Spacing[4],
    overflow: 'hidden',
    ...Platform.select({
      ios: Shadows.sm,
      android: Shadows.sm,
    }),
  },

  cardContent: {
    flexDirection: 'row',
    alignItems: 'center',
  },

  iconSection: {
    marginRight: Spacing[4],
  },

  iconContainer: {
    borderRadius: BorderRadius.lg,
    justifyContent: 'center',
    alignItems: 'center',
    ...Platform.select({
      ios: Shadows.xs,
      android: Shadows.xs,
    }),
  },

  textSection: {
    flex: 1,
    paddingRight: Spacing[2],
  },

  arrowSection: {
    justifyContent: 'center',
    alignItems: 'center',
    ...Accessibility.touchTarget,
  },

  // Size Variants
  compactCard: {
    paddingVertical: Spacing[3],
    paddingHorizontal: Spacing[4],
  },

  standardCard: {
    paddingVertical: Spacing[5],
    paddingHorizontal: Spacing[6],
  },

  largeCard: {
    paddingVertical: Spacing[6],
    paddingHorizontal: Spacing[8],
  },

  // Icon Styles
  icon: {
    textAlign: 'center',
  },

  compactIcon: {
    fontSize: Typography.sizes.lg,
  },

  standardIcon: {
    fontSize: Typography.sizes['2xl'],
  },

  largeIcon: {
    fontSize: Typography.sizes['3xl'],
  },

  compactIconContainer: {
    width: 32,
    height: 32,
  },

  standardIconContainer: {
    width: 48,
    height: 48,
  },

  largeIconContainer: {
    width: 56,
    height: 56,
  },

  // Typography Styles
  title: {
    fontWeight: Typography.weights.semibold,
    marginBottom: Spacing[1],
    includeFontPadding: false,
    textAlignVertical: 'center',
  },

  compactTitle: {
    fontSize: Typography.sizes.base,
    lineHeight: Typography.lineHeights.snug * Typography.sizes.base,
  },

  standardTitle: {
    fontSize: Typography.sizes.lg,
    lineHeight: Typography.lineHeights.snug * Typography.sizes.lg,
  },

  largeTitle: {
    fontSize: Typography.sizes.xl,
    lineHeight: Typography.lineHeights.snug * Typography.sizes.xl,
  },

  subtitle: {
    fontWeight: Typography.weights.medium,
    includeFontPadding: false,
    textAlignVertical: 'center',
  },

  compactSubtitle: {
    fontSize: Typography.sizes.xs,
    lineHeight: Typography.lineHeights.normal * Typography.sizes.xs,
  },

  standardSubtitle: {
    fontSize: Typography.sizes.sm,
    lineHeight: Typography.lineHeights.normal * Typography.sizes.sm,
  },

  largeSubtitle: {
    fontSize: Typography.sizes.base,
    lineHeight: Typography.lineHeights.normal * Typography.sizes.base,
  },

  arrow: {
    fontSize: Typography.sizes.lg,
    fontWeight: Typography.weights.semibold,
  },

  // Default Variant
  defaultCard: {
    backgroundColor: Colors.neutral[0],
    borderWidth: 1,
    borderColor: Colors.neutral[200],
  },

  defaultIconContainer: {
    backgroundColor: Colors.neutral[100],
  },

  defaultIcon: {
    color: Colors.neutral[700],
  },

  defaultTitle: {
    color: Colors.neutral[900],
  },

  defaultSubtitle: {
    color: Colors.neutral[600],
  },

  defaultArrow: {
    color: Colors.primary[500],
  },

  // Primary Variant
  primaryCard: {
    backgroundColor: Colors.primary[500],
    borderWidth: 0,
    ...Platform.select({
      ios: Shadows.primary,
      android: Shadows.primary,
    }),
  },

  primaryIconContainer: {
    backgroundColor: Colors.primary[600],
  },

  primaryIcon: {
    color: Colors.neutral[0],
  },

  primaryTitle: {
    color: Colors.neutral[0],
  },

  primarySubtitle: {
    color: Colors.primary[100],
  },

  primaryArrow: {
    color: Colors.neutral[0],
  },

  // Elevated Variant
  elevatedCard: {
    backgroundColor: Colors.neutral[0],
    borderWidth: 0,
    ...(Platform.OS === 'ios'
      ? {
          shadowColor: Colors.neutral[900],
          shadowOffset: { width: 0, height: 8 },
          shadowOpacity: 0.15,
          shadowRadius: 12,
        }
      : {}),
    ...(Platform.OS === 'android' ? { elevation: 6 } : {}),
  },

  elevatedIconContainer: {
    backgroundColor: Colors.primary[50],
  },

  elevatedIcon: {
    color: Colors.primary[600],
  },

  elevatedTitle: {
    color: Colors.neutral[900],
  },

  elevatedSubtitle: {
    color: Colors.neutral[600],
  },

  elevatedArrow: {
    color: Colors.primary[500],
  },

  // Disabled State
  disabledCard: {
    opacity: 0.6,
  },
});

export default EnhancedCard;

import * as Haptics from 'expo-haptics';
import React, { useCallback, useRef } from 'react';
import type { TouchableOpacityProps } from 'react-native';
import { Animated, Easing, StyleSheet, TouchableOpacity } from 'react-native';

import { Animation, Glassmorphism } from '../constants/designTokens';

interface EnhancedTouchableProps extends TouchableOpacityProps {
  readonly children: React.ReactNode;
  readonly variant?: 'default' | 'glass' | 'neon' | 'minimal';
  readonly microAnimation?: 'scale' | 'lift' | 'glow' | 'bounce' | 'none';
  readonly hapticFeedback?: boolean;
  readonly loading?: boolean;
  readonly disabled?: boolean;
  readonly onPress?: () => void;
}

// Animation Handlers Custom Hook
const useAnimationHandlers = (
  microAnimation: EnhancedTouchableProps['microAnimation'],
  scaleAnim: Animated.Value,
  elevationAnim: Animated.Value,
  glowAnim: Animated.Value
) => {
  const executePressInAnimation = useCallback(() => {
    switch (microAnimation) {
      case 'scale':
        Animated.timing(scaleAnim, {
          toValue: 0.95,
          duration: Animation.duration.ultraFast,
          easing: Easing.out(Easing.quad),
          useNativeDriver: true,
        }).start();
        break;

      case 'lift':
        Animated.parallel([
          Animated.timing(scaleAnim, {
            toValue: 1.02,
            duration: Animation.duration.fast,
            easing: Easing.out(Easing.quad),
            useNativeDriver: true,
          }),
          Animated.timing(elevationAnim, {
            toValue: 8,
            duration: Animation.duration.fast,
            easing: Easing.out(Easing.quad),
            useNativeDriver: false,
          }),
        ]).start();
        break;

      case 'glow':
        Animated.timing(glowAnim, {
          toValue: 1,
          duration: Animation.duration.normal,
          easing: Easing.out(Easing.quad),
          useNativeDriver: false,
        }).start();
        break;

      case 'bounce':
        Animated.sequence([
          Animated.timing(scaleAnim, {
            toValue: 1.1,
            duration: Animation.duration.ultraFast,
            easing: Easing.out(Easing.quad),
            useNativeDriver: true,
          }),
          Animated.spring(scaleAnim, {
            toValue: 1,
            tension: Animation.spring.playful.tension,
            friction: Animation.spring.playful.friction,
            useNativeDriver: true,
          }),
        ]).start();
        break;

      default:
        break;
    }
  }, [microAnimation, scaleAnim, elevationAnim, glowAnim]);

  const executePressOutAnimation = useCallback(() => {
    switch (microAnimation) {
      case 'scale':
        Animated.timing(scaleAnim, {
          toValue: 1,
          duration: Animation.duration.fast,
          easing: Easing.out(Easing.quad),
          useNativeDriver: true,
        }).start();
        break;

      case 'lift':
        Animated.parallel([
          Animated.timing(scaleAnim, {
            toValue: 1,
            duration: Animation.duration.fast,
            easing: Easing.out(Easing.quad),
            useNativeDriver: true,
          }),
          Animated.timing(elevationAnim, {
            toValue: 0,
            duration: Animation.duration.fast,
            easing: Easing.out(Easing.quad),
            useNativeDriver: false,
          }),
        ]).start();
        break;

      case 'glow':
        Animated.timing(glowAnim, {
          toValue: 0,
          duration: Animation.duration.normal,
          easing: Easing.out(Easing.quad),
          useNativeDriver: false,
        }).start();
        break;

      default:
        break;
    }
  }, [microAnimation, scaleAnim, elevationAnim, glowAnim]);

  return { executePressInAnimation, executePressOutAnimation };
};

// Simplified Enhanced Touchable Animations Hook
const useEnhancedTouchableAnimations = (
  microAnimation: EnhancedTouchableProps['microAnimation'],
  hapticFeedback: boolean,
  disabled: boolean,
  loading: boolean,
  onPress?: () => void
) => {
  // Animation values
  const scaleAnim = useRef(new Animated.Value(1)).current;
  const elevationAnim = useRef(new Animated.Value(0)).current;
  const glowAnim = useRef(new Animated.Value(0)).current;
  const rotateAnim = useRef(new Animated.Value(0)).current;

  const { executePressInAnimation, executePressOutAnimation } =
    useAnimationHandlers(microAnimation, scaleAnim, elevationAnim, glowAnim);

  const handlePressIn = useCallback(() => {
    // Haptic feedback
    if (hapticFeedback && !disabled) {
      void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    }
    executePressInAnimation();
  }, [hapticFeedback, disabled, executePressInAnimation]);

  const handlePressOut = useCallback(() => {
    executePressOutAnimation();
  }, [executePressOutAnimation]);

  const handlePress = useCallback(() => {
    if (!disabled && !loading && onPress) {
      // Success feedback animation
      if (microAnimation !== 'none') {
        Animated.sequence([
          Animated.timing(rotateAnim, {
            toValue: 1,
            duration: Animation.duration.fast,
            easing: Easing.linear,
            useNativeDriver: true,
          }),
          Animated.timing(rotateAnim, {
            toValue: 0,
            duration: 0,
            useNativeDriver: true,
          }),
        ]).start();
      }
      onPress();
    }
  }, [disabled, loading, onPress, microAnimation, rotateAnim]);

  return {
    scaleAnim,
    elevationAnim,
    glowAnim,
    rotateAnim,
    handlePressIn,
    handlePressOut,
    handlePress,
  };
};

// Custom Hook for Enhanced Touchable Styles
const useEnhancedTouchableStyles = (
  variant: EnhancedTouchableProps['variant'],
  glowAnim: Animated.Value
) => {
  const getVariantStyle = useCallback(() => {
    switch (variant) {
      case 'glass':
        return [
          styles.glassVariant,
          {
            ...Glassmorphism.light,
            shadowOpacity: glowAnim.interpolate({
              inputRange: [0, 1],
              outputRange: [0.1, 0.3],
            }),
          },
        ];

      case 'neon':
        return [
          styles.neonVariant,
          {
            shadowOpacity: glowAnim.interpolate({
              inputRange: [0, 1],
              outputRange: [0.3, 0.8],
            }),
            shadowRadius: glowAnim.interpolate({
              inputRange: [0, 1],
              outputRange: [10, 25],
            }),
          },
        ];

      case 'minimal':
        return styles.minimalVariant;

      default:
        return styles.defaultVariant;
    }
  }, [variant, glowAnim]);

  return { getVariantStyle };
};

// Main Component - Now much smaller
export const EnhancedTouchable: React.FC<EnhancedTouchableProps> = ({
  children,
  style,
  variant = 'default',
  microAnimation = 'scale',
  hapticFeedback = true,
  loading = false,
  disabled = false,
  onPress,
  ...props
}) => {
  // Use custom hooks
  const {
    scaleAnim,
    elevationAnim,
    glowAnim,
    rotateAnim,
    handlePressIn,
    handlePressOut,
    handlePress,
  } = useEnhancedTouchableAnimations(
    microAnimation,
    hapticFeedback,
    disabled,
    loading,
    onPress
  );

  const { getVariantStyle } = useEnhancedTouchableStyles(variant, glowAnim);

  // Loading animation effect
  React.useEffect(() => {
    if (loading) {
      const loadingAnimation = Animated.loop(
        Animated.sequence([
          Animated.timing(scaleAnim, {
            toValue: 1.05,
            duration: 800,
            easing: Easing.inOut(Easing.quad),
            useNativeDriver: true,
          }),
          Animated.timing(scaleAnim, {
            toValue: 1,
            duration: 800,
            easing: Easing.inOut(Easing.quad),
            useNativeDriver: true,
          }),
        ])
      );
      loadingAnimation.start();
      return () => {
        loadingAnimation.stop();
      };
    }
    return undefined;
  }, [loading, scaleAnim]);

  // Render
  return (
    <Animated.View
      style={[
        getVariantStyle(),
        {
          transform: [
            { scale: scaleAnim },
            {
              rotate: rotateAnim.interpolate({
                inputRange: [0, 1],
                outputRange: ['0deg', '360deg'],
              }),
            },
          ],
          elevation: elevationAnim,
        },
        style,
      ]}
    >
      <TouchableOpacity
        onPressIn={handlePressIn}
        onPressOut={handlePressOut}
        onPress={handlePress}
        disabled={disabled || loading}
        activeOpacity={0.9}
        style={{ flex: 1 }}
        {...props}
      >
        {children}
      </TouchableOpacity>
    </Animated.View>
  );
};

const styles = StyleSheet.create({
  defaultVariant: {
    // Default styling - will be overridden by parent styles
  },

