    lineHeight: windowWidth < 375 ? 32 : 36,
  },
  animations: {
    staggerDelay: 150,
    fadeInDuration: 900,
  },
  scrollEffects: {
    fadeRange: [0, 150],
    translateRange: [0, 80],
    parallaxRange: [0, 350],
    scaleRange: [1, 1.08],
  },
};

// Hook for animations
const useHomeHeaderAnimations = () => {
  const titleAnim = useRef(new Animated.Value(0)).current;
  const imageAnim = useRef(new Animated.Value(0)).current;
  const containerAnim = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    Animated.sequence([
      Animated.timing(containerAnim, {
        toValue: 1,
        duration: ADVANCED_CONFIG.animations.fadeInDuration * 0.6,
        useNativeDriver: true,
      }),
      Animated.stagger(ADVANCED_CONFIG.animations.staggerDelay, [
        Animated.spring(titleAnim, {
          toValue: 1,
          useNativeDriver: true,
          tension: 100,
          friction: 8,
        }),
        Animated.timing(imageAnim, {
          toValue: 1,
          duration: ADVANCED_CONFIG.animations.fadeInDuration,
          useNativeDriver: true,
        }),
      ]),
    ]).start();
  }, [containerAnim, titleAnim, imageAnim]);

  return { titleAnim, imageAnim, containerAnim };
};

// Hook for scroll interpolations
const useScrollInterpolations = (scrollY: Animated.Value) => {
  const titleOpacity = scrollY.interpolate({
    inputRange: ADVANCED_CONFIG.scrollEffects.fadeRange,
    outputRange: [1, 0],
    extrapolate: 'clamp',
  });

  const titleTransform = scrollY.interpolate({
    inputRange: ADVANCED_CONFIG.scrollEffects.translateRange,
    outputRange: [0, -40],
    extrapolate: 'clamp',
  });

  const imageParallax = scrollY.interpolate({
    inputRange: ADVANCED_CONFIG.scrollEffects.parallaxRange,
    outputRange: [0, -100],
    extrapolate: 'clamp',
  });

  const imageScale = scrollY.interpolate({
    inputRange: [0, 300],
    outputRange: ADVANCED_CONFIG.scrollEffects.scaleRange,
    extrapolate: 'clamp',
  });

  const gradientOpacity = scrollY.interpolate({
    inputRange: [0, 200],
    outputRange: [0.1, 0.3],
    extrapolate: 'clamp',
  });

  return {
    titleOpacity,
    titleTransform,
    imageParallax,
    imageScale,
    gradientOpacity,
  };
};

