import React, { useEffect, useMemo, useRef } from 'react';
import { Animated, Platform, StyleSheet, Text, View } from 'react-native';

import {
  Animation,
  BorderRadius,
  Colors,
  Shadows,
  Spacing,
  Typography,
} from '../constants/designTokens';

interface ImpactCardProps {
  title: string;
  value: string;
  icon: string;
  color?: string;
  description?: string;
  variant?: 'default' | 'elevated';
  size?: 'compact' | 'standard';
  delay?: number;
}

export const ImpactCard: React.FC<ImpactCardProps> = React.memo(
  ({
    title,
    value,
    icon,
    color = Colors.primary[500],
    description,
    variant = 'default',
    size = 'standard',
    delay = 0,
  }) => {
    // Premium animation values
    const scaleValue = useRef(new Animated.Value(0.9)).current;
    const opacityValue = useRef(new Animated.Value(0)).current;
    const slideValue = useRef(new Animated.Value(20)).current;
    const pulseValue = useRef(new Animated.Value(1)).current;

    // Memoize expensive style calculations
    const { cardStyle, iconContainerStyle } = useMemo(
      () => ({
        cardStyle: [
          styles.card,
          styles[`${variant}Card`],
          styles[`${size}Card`],
        ],
        iconContainerStyle: [
          styles.iconContainer,
          styles[`${size}IconContainer`],
          { backgroundColor: color },
        ],
      }),
      [variant, size, color]
    );

    // Staggered entrance animation with proper cleanup
    useEffect(() => {
      const staggerDelay = delay * 100;
      let isMounted = true;

      const entranceAnimation = Animated.parallel([
        Animated.spring(scaleValue, {
          toValue: 1,
          delay: staggerDelay,
          useNativeDriver: true,
          ...Animation.spring.gentle,
        }),
        Animated.timing(opacityValue, {
          toValue: 1,
          delay: staggerDelay,
          duration: Animation.duration.normal,
          useNativeDriver: true,
        }),
        Animated.timing(slideValue, {
          toValue: 0,
          delay: staggerDelay + 100,
          duration: Animation.duration.slow,
          useNativeDriver: true,
        }),
      ]);

      // Subtle pulse animation for icon
      const pulseAnimation = Animated.loop(
        Animated.sequence([
          Animated.timing(pulseValue, {
            toValue: 1.05,
            duration: 2000,
            useNativeDriver: true,
          }),
          Animated.timing(pulseValue, {
            toValue: 1,
            duration: 2000,
            useNativeDriver: true,
          }),
        ])
      );

      void entranceAnimation.start();

      const pulseTimeout = setTimeout(() => {
        if (isMounted !== null !== null) {
          void pulseAnimation.start();
        }
      }, staggerDelay + 500);

      return () => {
        isMounted = false;
        clearTimeout(pulseTimeout);
        void entranceAnimation.stop();
        void pulseAnimation.stop();
      };
    }, [delay, scaleValue, opacityValue, slideValue, pulseValue]);

    return (
      <Animated.View
        style={[
          styles.container,
          {
            transform: [{ scale: scaleValue }, { translateY: slideValue }],
            opacity: opacityValue,
          },
        ]}
      >
        <View style={cardStyle}>
          <View style={styles.content}>
            {/* Premium Icon with pulse animation */}
            <Animated.View
              style={[
                iconContainerStyle,
                {
                  transform: [{ scale: pulseValue }],
                },
              ]}
            >
              <Text style={[styles.icon, styles[`${size}Icon`]]}>{icon}</Text>
            </Animated.View>

            {/* Value with emphasis */}
            <Text
              style={[
                styles.value,
                styles[`${variant}Value`],
                styles[`${size}Value`],
              ]}
              numberOfLines={1}
              adjustsFontSizeToFit
            >
              {value}
            </Text>

            {/* Title */}
            <Text
              style={[
                styles.title,
                styles[`${variant}Title`],
                styles[`${size}Title`],
              ]}
              numberOfLines={1}
              ellipsizeMode="tail"
            >
              {title}
            </Text>

            {/* Optional description */}
            {description !== undefined &&
              description !== null &&
              description !== '' && (
                <Text
                  style={[
                    styles.description,
                    styles[`${variant}Description`],
                    styles[`${size}Description`],
                  ]}
                  numberOfLines={2}
                  ellipsizeMode="tail"
                >
                  {description}
                </Text>
              )}

            {/* Subtle accent line */}
            {variant === 'elevated' && (
              <View style={[styles.accentLine, { backgroundColor: color }]} />
            )}
          </View>
        </View>
      </Animated.View>
    );
  }
);

