// CONTENT RENDERER - Extracted component logic
// ===================================================================
const CTAContent: React.FC<{
  description: string | undefined;
  title: string;
  subtitle: string | undefined;
  variant: 'primary' | 'secondary' | 'gradient';
  size: 'compact' | 'standard' | 'large';
  contentStyles: ReturnType<typeof createContentStyles>;
  typographyStyles: ReturnType<typeof createTypographyStyles>;
  shimmerValue: Animated.Value;
}> = ({
  description,
  title,
  subtitle,
  variant,
  size,
  contentStyles,
  typographyStyles,
  shimmerValue,
}) => (
  <View style={contentStyles.content}>
    {description && (
      <Text
        style={[
          contentStyles.description,
          typographyStyles[`${variant}Description`],
          typographyStyles[`${size}Description`],
        ]}
        numberOfLines={2}
        ellipsizeMode="tail"
      >
        {description}
      </Text>
    )}

    <Text
      style={[
        contentStyles.title,
        typographyStyles[`${variant}Title`],
        typographyStyles[`${size}Title`],
      ]}
      numberOfLines={2}
      ellipsizeMode="tail"
    >
      {title}
    </Text>

    {subtitle && (
      <Text
        style={[
          contentStyles.subtitle,
          typographyStyles[`${variant}Subtitle`],
          typographyStyles[`${size}Subtitle`],
        ]}
        numberOfLines={2}
        ellipsizeMode="tail"
      >
        {subtitle}
      </Text>
    )}

    {/* Premium accent indicator */}
    {variant === 'gradient' && (
      <Animated.View
        style={[
          contentStyles.accentLine,
          {
            opacity: shimmerValue.interpolate({
              inputRange: [0, 0.5, 1],
              outputRange: [0.3, 1, 0.3],
            }),
          },
        ]}
      />
    )}
  </View>
);

// ===================================================================
// MAIN COMPONENT - Now clean and focused
// ===================================================================
const ModernCTA: React.FC<ModernCTAProps> = ({
  title,
  subtitle,
  description,
  onPress,
  variant = 'primary',
  size = 'standard',
  disabled = false,
  accessibilityLabel,
  accessibilityHint,
}) => {
  const { colors } = useTheme();

  const containerStyles = React.useMemo(() => createContainerStyles(), []);
  const buttonStyles = React.useMemo(
    () => createButtonStyles(colors),
    [colors]
  );
  const contentStyles = React.useMemo(
    () => createContentStyles(colors),
    [colors]
  );
  const typographyStyles = React.useMemo(
    () => createTypographyStyles(colors),
    [colors]
  );

  const { scaleValue, shimmerValue, handlePressIn, handlePressOut } =
    useModernCTAAnimations();

  // Accessibility configuration
  const accessibilityConfig = React.useMemo(
    () => ({
      accessible: true,
      accessibilityRole: 'button' as const,
      accessibilityLabel: accessibilityLabel ?? title,
      accessibilityHint: accessibilityHint ?? 'Tocca per continuare',
      accessibilityState: { disabled },
      ...Accessibility.touchTarget,
    }),
    [accessibilityLabel, title, accessibilityHint, disabled]
  );

  // Dynamic styles
  const containerStyle = [
    containerStyles.container,
    containerStyles[`${size}Container` as keyof typeof containerStyles],
  ];
  const buttonStyle = [
    buttonStyles.baseButton,
    buttonStyles[`${variant}Button` as keyof typeof buttonStyles],
    buttonStyles[`${size}Button` as keyof typeof buttonStyles],
    disabled && buttonStyles.disabledButton,
  ];

  const contentProps = {
    description,
    title,
    subtitle,
    variant,
    size,
    contentStyles,
    typographyStyles,
    shimmerValue,
  };

  // Gradient variant with premium effects
  if (variant === 'gradient') {
    return (
      <View style={containerStyle}>
        <Animated.View style={[{ transform: [{ scale: scaleValue }] }]}>
          <TouchableOpacity
            onPress={onPress}
            onPressIn={handlePressIn}
            onPressOut={handlePressOut}
            disabled={disabled}
            activeOpacity={1}
            {...accessibilityConfig}
          >
            <LinearGradient
              colors={colors.gradients.energy}
              start={{ x: 0, y: 0 }}
              end={{ x: 1, y: 1 }}
              style={[buttonStyle, buttonStyles.gradientButton]}
            >
              <Animated.View
                style={[
                  contentStyles.shimmerOverlay,
                  {
                    opacity: shimmerValue.interpolate({
                      inputRange: [0, 1],
                      outputRange: [0, 0.3],
                    }),
                  },
                ]}
              />
              <CTAContent {...contentProps} />
            </LinearGradient>
          </TouchableOpacity>
        </Animated.View>
      </View>
    );
  }

  // Standard variants
  return (
    <View style={containerStyle}>
      <Animated.View style={[{ transform: [{ scale: scaleValue }] }]}>
        <TouchableOpacity
          style={buttonStyle}
          onPress={onPress}
          onPressIn={handlePressIn}
          onPressOut={handlePressOut}
          disabled={disabled}
          activeOpacity={1}
          {...accessibilityConfig}
        >
          <CTAContent {...contentProps} />
        </TouchableOpacity>
      </Animated.View>
    </View>
  );
};

export default ModernCTA;

