import React, { useCallback, useEffect, useMemo, useRef } from 'react';
import {
  Animated,
  Dimensions,
  StyleSheet,
  Text,
  TouchableOpacity,
} from 'react-native';

import {
  BorderRadius,
  Shadows,
  Spacing,
  Typography,
} from '../constants/designTokens';
import { useHapticFeedback } from '../hooks/useHapticFeedback';
import { useTheme } from '../hooks/useTheme';

const { width } = Dimensions.get('window');

interface PremiumFloatingButtonProps {
  readonly onPress?: () => void;
  readonly title?: string;
  readonly icon?: string;
  readonly position?: 'bottom-right' | 'bottom-center' | 'bottom-left';
  readonly variant?: 'primary' | 'gradient' | 'glass';
}

// Hook for animations
const usePremiumFloatingButtonAnimations = () => {
  const { buttonPress, pulsePattern } = useHapticFeedback();

  const scaleValue = useRef(new Animated.Value(1)).current;
  const pulseValue = useRef(new Animated.Value(1)).current;
  const glowValue = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    const pulseAnimation = Animated.loop(
      Animated.sequence([
        Animated.timing(pulseValue, {
          toValue: 1.05,
          duration: 2000,
          useNativeDriver: true,
        }),
        Animated.timing(pulseValue, {
          toValue: 1,
          duration: 2000,
          useNativeDriver: true,
        }),
      ])
    );
    void pulseAnimation.start();
    return () => {
      void pulseAnimation.stop();
    };
  }, [pulseValue]);

  const handlePressIn = useCallback(() => {
    void buttonPress();
    Animated.parallel([
      Animated.spring(scaleValue, {
        toValue: 0.95,
        useNativeDriver: true,
        tension: 300,
        friction: 10,
      }),
      Animated.timing(glowValue, {
        toValue: 1,
        duration: 150,
        useNativeDriver: true,
      }),
    ]).start();
  }, [buttonPress, scaleValue, glowValue]);

  const handlePressOut = useCallback(() => {
    Animated.parallel([
      Animated.spring(scaleValue, {
        toValue: 1,
        useNativeDriver: true,
        tension: 300,
        friction: 10,
      }),
      Animated.timing(glowValue, {
        toValue: 0,
        duration: 200,
        useNativeDriver: true,
      }),
    ]).start();
  }, [scaleValue, glowValue]);

  const handlePress = useCallback(
    (onPress?: () => void) => {
      void pulsePattern();
      onPress?.();
    },
    [pulsePattern]
  );

  return {
    scaleValue,
    pulseValue,
    glowValue,
    handlePressIn,
    handlePressOut,
    handlePress,
  };
};

// Hook for position calculation
const usePositionStyle = (position: string) => {
  return useMemo(() => {
    const baseStyle = {
      position: 'absolute' as const,
      bottom: Spacing[8],
      zIndex: 1000,
    };

    switch (position) {
      case 'bottom-center':
        return { ...baseStyle, left: width / 2 - 75 };
      case 'bottom-left':
        return { ...baseStyle, left: Spacing[6] };
      case 'bottom-right':
      default:
        return { ...baseStyle, right: Spacing[6] };
    }
  }, [position]);
};

// Hook for styles
const usePremiumFloatingButtonStyles = (variant: string, position: string) => {
  const { colors } = useTheme();
  const positionStyle = usePositionStyle(position);

  return useMemo(
    () =>
