        },
        glassButton: {
          backgroundColor: 'rgba(255, 255, 255, 0.2)',
          borderWidth: 1,
          borderColor: 'rgba(255, 255, 255, 0.3)',
        },
        content: {
          flexDirection: 'row',
          alignItems: 'center',
          gap: Spacing[2],
        },
        icon: {
          fontSize: 20,
        },
        title: {
          color: colors.neutral[0],
          fontSize: Typography.sizes.base,
          fontWeight: Typography.weights.bold,
          textShadowColor: 'rgba(0, 0, 0, 0.3)',
          textShadowOffset: { width: 0, height: 1 },
          textShadowRadius: 2,
        },
        glassTitle: {
          color: colors.neutral[900],
          textShadowColor: 'rgba(255, 255, 255, 0.5)',
        },
        glow: {
          position: 'absolute',
          top: -5,
          left: -5,
          right: -5,
          bottom: -5,
          borderRadius: BorderRadius.full,
          backgroundColor: colors.primary[400],
          opacity: 0.3,
        },
      }),
    [colors, positionStyle]
  );
};

// Main Component - Now much smaller
export const PremiumFloatingButton: React.FC<PremiumFloatingButtonProps> = ({
  onPress,
  title = 'Aiuta Ora',
  icon = '💝',
  position = 'bottom-right',
  variant = 'gradient',
}) => {
  const {
    scaleValue,
    pulseValue,
    glowValue,
    handlePressIn,
    handlePressOut,
    handlePress,
  } = usePremiumFloatingButtonAnimations();

  const styles = usePremiumFloatingButtonStyles(variant, position);

  const animatedStyle = {
    transform: [{ scale: Animated.multiply(scaleValue, pulseValue) }],
  };

  const glowStyle = {
    opacity: glowValue,
    transform: [
      {
        scale: glowValue.interpolate({
          inputRange: [0, 1],
          outputRange: [1, 1.2],
        }),
      },
    ],
  };

  return (
    <Animated.View style={[styles.container, animatedStyle]}>
      <Animated.View style={[styles.glow, glowStyle]} />
      <TouchableOpacity
        style={[
          styles.button,
          variant === 'glass' ? styles.glassButton : styles.primaryButton,
        ]}
        onPress={() => handlePress(onPress)}
        onPressIn={handlePressIn}
        onPressOut={handlePressOut}
        activeOpacity={1}
        accessible
        accessibilityRole="button"
        accessibilityLabel={`${title} - Pulsante di azione rapida`}
      >
        <Animated.View style={styles.content}>
          <Text style={styles.icon}>{icon}</Text>
          <Text
            style={[styles.title, variant === 'glass' && styles.glassTitle]}
          >
            {title}
          </Text>
        </Animated.View>
      </TouchableOpacity>
    </Animated.View>
  );
};

