// Hook for navigation handlers
const useImpactScreenHandlers = (navigation: ImpactTabScreenNavigationProp) => {
  const { triggerHaptic } = useHapticFeedback();

  const handleDetailPress = useCallback(
    (_statId: string) => {
      void triggerHaptic('medium');
      navigation.navigate('Impatto2024');
    },
    [triggerHaptic, navigation]
  );

  const handleProjectsPress = useCallback(() => {
    void triggerHaptic('medium');
    navigation.navigate('Progetti');
  }, [triggerHaptic, navigation]);

  const createStatPressHandler = useCallback(
    (statId: string) => {
      return () => {
        handleDetailPress(statId);
      };
    },
    [handleDetailPress]
  );

  return {
    handleDetailPress,
    handleProjectsPress,
    createStatPressHandler,
  };
};

type StylesType = Record<string, any>;

const StatCard = ({
  stat,
  _index,
  styles,
  fadeAnim,
  slideAnim,
  handleDetailPress,
}: {
  readonly stat: {
    readonly id: string;
    readonly icon: string;
    readonly value: string;
    readonly label: string;
    readonly target: string;
    readonly progress: number;
    readonly color: string;
  };
  readonly _index: number;
  readonly styles: StylesType;
  readonly fadeAnim: Animated.Value;
  readonly slideAnim: Animated.Value;
  readonly handleDetailPress: () => void;
}) => (
  <Animated.View
    style={[
      styles.statCard,
      {
        opacity: fadeAnim,
        transform: [
          {
            translateY: slideAnim.interpolate({
              inputRange: [0, 50],
              outputRange: [0, 50],
            }),
          },
        ],
      },
    ]}
  >
    <TouchableRipple
      onPress={handleDetailPress}
      borderless
      style={{ borderRadius: BorderRadius.xl }}
