// Custom Hook for Projects Screen Logic
const useProjectsScreenLogic = () => {
  const {
    projects,
    getActiveProjects: _getActiveProjects,
    getCompletedProjects: _getCompletedProjects,
    getUpcomingProjects: _getUpcomingProjects,
    getProjectStats,
  } = useProjectsData();

  const [activeTab, setActiveTab] = useState('all');
  const [refreshing, setRefreshing] = useState(false);

  const stats = getProjectStats();

  const tabs = useMemo(
    () => [
      {
        id: 'all',
        label: 'Tutti',
        count: stats.total,
        icon: '📋',
      },
      {
        id: 'active',
        label: 'In Corso',
        count: stats.active,
        icon: '🚀',
      },
      {
        id: 'completed',
        label: 'Completati',
        count: stats.completed,
        icon: '✅',
      },
      {
        id: 'upcoming',
        label: 'Prossimi',
        count: stats.upcoming,
        icon: '⏳',
      },
    ],
    [stats]
  );

  const getFilteredProjects = useCallback(() => {
    switch (activeTab) {
      case 'active':
        return projects.filter((project: any) => project.status === 'active');
      case 'completed':
        return projects.filter(
          (project: any) => project.status === 'completed'
        );
      case 'upcoming':
        return projects.filter((project: any) => project.status === 'upcoming');
      default:
        return projects;
    }
  }, [activeTab, projects]);

  const handleRefresh = useCallback(async () => {
    setRefreshing(true);
    await new Promise(resolve => setTimeout(resolve, 1500));
    setRefreshing(false);
  }, []);

  const handleProjectPress = useCallback((_projectId: string) => {
    // Navigation logic here - removed console.log for no-console
    // TODO: Implement navigation to project detail
  }, []);

  const createProjectPressHandler = useCallback(
    (projectId: string) => {
      return () => {
        handleProjectPress(projectId);
      };
    },
    [handleProjectPress]
  );

  const getSectionTitle = useCallback(() => {
    switch (activeTab) {
      case 'all':
        return 'Tutti i Progetti';
      case 'active':
        return 'Progetti in Corso';
      case 'completed':
        return 'Progetti Completati';
      case 'upcoming':
        return 'Progetti Prossimi';
      default:
        return 'Progetti';
    }
  }, [activeTab]);

  return {
    projects,
    activeTab,
    setActiveTab,
    refreshing,
    stats,
    tabs,
    filteredProjects: getFilteredProjects(),
    handleRefresh,
    createProjectPressHandler,
    getSectionTitle,
  };
};

